from fastapi import FastAPI, APIRouter
import pytest

def test_app_frontend():
    app = FastAPI()
    try:
        app.frontend("/", directory="dist")
    except AttributeError as e:
        print(f"Caught expected AttributeError: {e}")
        raise e

def test_router_frontend():
    router = APIRouter()
    try:
        router.frontend("/", directory="dist")
    except AttributeError as e:
        print(f"Caught expected AttributeError: {e}")
        raise e

if __name__ == "__main__":
    try:
        test_app_frontend()
        print("test_app_frontend passed unexpectedly")
    except AttributeError:
        print("test_app_frontend failed as expected")

    try:
        test_router_frontend()
        print("test_router_frontend passed unexpectedly")
    except AttributeError:
        print("test_router_frontend failed as expected")
